create schema tkt_private; create schema auth; create schema vault; create schema net; create schema cron; create role anon; create role authenticated; create role service_role;
create table public.tkt_notifications (id uuid,user_id uuid,event_key text,kind text,title text,body text,target jsonb,created_at timestamptz,read_at timestamptz,expires_at timestamptz);
create table public.tkt_offers (id uuid,ride_id uuid,captain_id uuid,attempt int4,status text,eta_s int4,created_at timestamptz,expires_at timestamptz);
create table public.tkt_profiles (user_id uuid,name text,phone text,captain bool,blocked bool,expires_at timestamptz,online bool,lat float8,lng float8,location_at timestamptz,created_at timestamptz,avatar_path text,privacy_version text,privacy_accepted_at timestamptz,gender text,deleted_at timestamptz);
create table public.tkt_rides (id uuid,quote_id uuid,rider_id uuid,captain_id uuid,status text,pickup jsonb,destination jsonb,geometry jsonb,fare int4,distance_m int4,duration_s int4,created_at timestamptz,updated_at timestamptz,pickup_name text,destination_name text,dispatch_state text,search_deadline timestamptz,captain_eta_s int4,eta_at timestamptz,route_distance_m numeric,base_fare int4,night_surcharge int4,priced_at timestamptz,pricing_version text,route_provider text,destination_revision int4,last_change_quote_id uuid,payment_method text,discount int4,customer_due int4,coupon_code text,round_trip bool,wait_minutes int4,waiting_fee int4,return_geometry jsonb,return_distance_m numeric,return_duration_s int4,round_trip_stage text,wait_started_at timestamptz,coupon_reward_type text,company_rate numeric);
create table tkt_private.captain_plans (user_id uuid,plan text,vehicle text,receive_food bool,receive_rides bool);
create table tkt_private.commerce_settings (id bool,commission_percent numeric,service_fee int4,captain_debt_limit int4,restaurant_debt_limit int4,updated_at timestamptz,restaurant_min_distance_m int4,restaurant_max_distance_m int4,food_first_distance_m int4,food_first_fee int4,food_max_distance_m int4,food_second_fee int4);
create table tkt_private.dispatch_locations (captain_id uuid,cell text,zone text,lat float8,lng float8,gps_at timestamptz,received_at timestamptz);
create table tkt_private.dispatch_settings (id bool,max_eta_s int4,search_s int4,stale_s int4,offer_s int4,h3_resolution int4,zones jsonb,mapbox_token text,lease_id uuid,lease_until timestamptz,last_worker_at timestamptz,last_error text,last_matrix_at timestamptz);
