create table tkt_private.restaurants (id uuid,owner_id uuid,name text,phone text,address text,description text,image_path text,location jsonb,open bool,created_at timestamptz,closing_time time,self_delivery bool,menu_categories jsonb);
alter table tkt_private.food_orders add primary key(id); alter table public.tkt_profiles add primary key(user_id);
